#'
#' Take weights of form P(X=x|G,R=1) from previous script and use
#' the P(G|R=1) probs to calculate P(X=x|R=1)
#'
#' Author: Kyla Chasalow
#'
#' AI Use: The first part was written by me. Checked by ChatGPT 6.1 Sol Medium for bugs.
#' Mainly it suggested the stopifnots below, which I added to be thorough.
#' Plotting code at the end of the script was generated by GPT and then
#' checked and tweaked by me.
#'
library(dplyr)
library(data.table)
library(ggplot2)
library(patchwork)

# Load output of 1_estimate_weights_from_voterfile.R
load_directory = "/n/holylabs/imai_lab/Lab/lroyden/files/counts_for_weights/estimated_weights/"
load_directory = "../../data/cluster_output/weight_calculations_from_voter_file/"
save_directory = "../../paper/Figures/weights/"
estimates_df <- data.table::fread(
  fs::path(load_directory, "estimated_weights_by_state.csv"),
  data.table = TRUE
)


# Load AJPP data
AJPP_directory = fs::path("/n/holylabs/LABS/imai_lab/Lab/lroyden/files/Brandeis_data/")
AJPP_directory = "../../data/DataObjects/"

p_state_gvn_R1 = readRDS(file.path(AJPP_directory, "p_state_gvn_R1.RDS"))
p_state_gvn_R1_table = data.table(
  "State" = names(p_state_gvn_R1),
  "p_state_gvn_R1" = unname(p_state_gvn_R1)
)
stopifnot(!anyDuplicated(p_state_gvn_R1_table$State))

# Left join to estimates on state column
estimates_df <- merge(
  estimates_df,
  p_state_gvn_R1_table,
  by = "State",
  all.x = TRUE,
  sort = FALSE
)
stopifnot(
  !anyNA(estimates_df$p_state_gvn_R1),
  !anyNA(estimates_df$Estimate)
)
estimates_df$prod = estimates_df$Estimate * estimates_df$p_state_gvn_R1

# Group_by variable and level and then sum over states
p_X_gvn_R1 <- estimates_df[
  ,
  .(estimate = sum(prod, na.rm = TRUE)),
  by = c("X_variable", "Variable_Level", "Est_type") #shouldn't need Est_type but just in case estimated same thing two ways
]

data.table::fwrite(
  p_X_gvn_R1,
  file.path(load_directory, "estimated_weights_overall.csv")
)

# Do this after the save so I know but results still save
distribution_totals <- p_X_gvn_R1[
  ,
  .(total = sum(estimate)),
  by = c("X_variable", "Est_type")
]
stopifnot(all(abs(distribution_totals$total - 1) < 1e-6))


#-------------------------------------------------------------------------------
# Create a version of p_X_gvn_R1 which removes the row of each X_variable that has value
# "Missing" and then re-normalizes the column "estimate"
#-------------------------------------------------------------------------------
library(dplyr)

p_X_gvn_R1_no_missing <- p_X_gvn_R1 %>%
  filter(Variable_Level != "Missing") %>%
  group_by(X_variable) %>%
  mutate(estimate = estimate / sum(estimate, na.rm = TRUE)) %>%
  ungroup()

data.table::fwrite(
  p_X_gvn_R1_no_missing,
  file.path(load_directory, "estimated_weights_overall_drop_missing.csv")
)


#-------------------------------------------------------------------------------
# EDA plots
#-------------------------------------------------------------------------------
library(ggplot2)

p_gender = p_X_gvn_R1_no_missing %>%
  filter(X_variable == "Gender") %>%
  ggplot(aes(x = Variable_Level, y = estimate)) +
  geom_col(fill = "black", width = 0.7) +
  scale_y_continuous(
    limits = c(0, 1),
    breaks = seq(0, 1, by = 0.2),
    expand = expansion(mult = c(0, 0))
  ) +
  labs(
    title = "Distribution over gender for Jewish population",
    x = NULL,
    y = "Estimated fraction"
  ) +
  theme_classic(base_size = 12) +
  theme(
    plot.title = element_text(face = "bold", hjust = 0.5),
    axis.text = element_text(color = "black"),
    axis.title.y = element_text(margin = margin(r = 10), size = 16),
    plot.margin = margin(15, 15, 15, 15),
    axis.text.x = element_text(size = 16),
    axis.text.y = element_text(size = 16),
    axis.title.x = element_text(size = 18)
  )

p_age = p_X_gvn_R1_no_missing %>%
  filter(X_variable == "Age") %>%
  mutate(Age = as.numeric(as.character(Variable_Level))) %>%
  ggplot(aes(x = Age, y = estimate)) +
  geom_line(color = "black", linewidth = 0.7) +
  geom_point(color = "black", size = 2) +
  scale_y_continuous(
    limits = c(0, .03),
    breaks = seq(0, .03, by = 0.01),
    expand = expansion(mult = c(0, 0))
  ) +
  labs(
    title = "Distribution over age for Jewish population",
    x = "",
    y = ""
  ) +
  theme_classic(base_size = 12) +
  theme(
    plot.title = element_text(face = "bold", hjust = 0.5),
    axis.text = element_text(color = "black"),
    axis.title.y = element_text(margin = margin(r = 10)),
    plot.margin = margin(15, 15, 15, 15),
    axis.text.x = element_text(size = 16),  # Age tick numbers
    axis.text.y = element_text(size = 16),  # Estimate tick numbers
    axis.title.x = element_text(size = 18) # "Age" axis label
  )

p_party = p_X_gvn_R1_no_missing %>%
  filter(X_variable == "Party") %>%
  mutate(
    Variable_Level = if_else(
      estimate < 0.01, "Other Parties", as.character(Variable_Level)
    )
  ) %>%
  group_by(X_variable, Variable_Level) %>%
  summarise(estimate = sum(estimate), .groups = "drop") %>%
  arrange(desc(estimate)) %>%
  mutate(Variable_Level = factor(Variable_Level, levels = Variable_Level)) %>%
  ggplot(aes(x = Variable_Level, y = estimate)) +
  geom_col(fill = "black", width = 0.7) +
  scale_y_continuous(
    limits = c(0, 1),
    breaks = seq(0, 1, by = 0.2),
    expand = expansion(mult = c(0, 0))
  ) +
  labs(
    title = "Distribution over party for Jewish population",
    x = NULL,
    y = ""
  ) +
  theme_classic(base_size = 12) +
  theme(
    plot.title = element_text(face = "bold", hjust = 0.5),
    axis.text = element_text(color = "black"),
    axis.title.y = element_text(margin = margin(r = 10)),
    plot.margin = margin(15, 15, 15, 15),
    axis.text.x = element_text(size = 12),
    axis.text.y = element_text(size = 16),
    axis.title.x = element_text(size = 18)
  )

# combine into one plot
p_combined <- (
  (p_gender + labs(title = "Gender") +
     theme(plot.title = element_text(size = 18))) |
    (p_age + labs(title = "Age") +
       theme(plot.title = element_text(size = 18))) |
    (p_party + labs(title = "Party") +
       theme(
         plot.title = element_text(size = 18),
         axis.text.x = element_text(angle = 0, hjust = 0.5)
       ))
) +
  plot_annotation(
    title = "Estimated Distributions Among Jewish Registered Voters",
    subtitle = "Based on BISG probabilities and voter file data",
    theme = theme(
      plot.title = element_text(face = "bold", hjust = 0, size = 18),
      plot.subtitle = element_text(hjust = 0, size = 14)
    )
  )

p_combined

ggsave(
  filename = file.path(save_directory, "estimated_weight_plots.pdf"),
  plot = p_combined,
  width = 17,
  height = 5,
  units = "in",
  dpi = 1200,
  bg = "white"
)




