         c(.8, .85,.9))
missingness_df[missingness_df$Age_fraction_missing > .007,
               c("State", "Age_fraction_missing")
]

p_X_gvn_R1 %>% filter(
  Variable_Level == "Unknown"
)


#-------------------------------------------------------------------------------
# Now create a plot that compares to Pew weights after aggregating in that way
#-------------------------------------------------------------------------------

pew_data_path = "../../data/Pew"
df_pew = read.csv(fs::path(pew_data_path,"pew_weights.csv"))
df_state2region = read.csv(fs::path(pew_data_path, "pew_state_to_region.csv"))

# Pew processing
#----------------
# Remove 1 =, 2 = etc. codes
df_pew <- df_pew |>
  mutate(
    Variable_Level = stringr::str_trim(
      stringr::str_remove(Variable_Level, "^\\s*\\d+\\s*=\\s*")
    )
  )
# Alignment between this and other table
df_pew <- df_pew |>
  mutate(
    Variable_Level = case_when(
      Variable_Level == "MALE" ~ "M",
      Variable_Level == "FEMALE" ~ "F",
      Variable_Level == "NOT ANSWERED" ~ "MISSING",
      Variable_Level == "NO ANSWER" ~ "MISSING",
      TRUE ~ as.character(Variable_Level)
    )
  )
# Capitalize only first letter
df_pew <- df_pew |>
  mutate(
    Variable_Level = stringr::str_to_sentence(Variable_Level),
    X_variable = stringr::str_to_sentence(X_variable)
  )


# VF based table processing
#---------------------------
# Bin the voter file based
age_proportions <- p_X_gvn_R1_no_missing |>
  filter(X_variable == "Age") |>
  mutate(
    Variable_Level = cut(
      as.numeric(as.character(Variable_Level)),
      breaks = c(18, 30, 50, 65, Inf),
      labels = c("18-29", "30-49", "50-64", "65+"),
      right = FALSE
    )
  ) |>
  filter(!is.na(Variable_Level)) |>
  group_by(X_variable, Variable_Level) |>
  summarise(estimate = sum(estimate, na.rm = TRUE), .groups = "drop") |>
  mutate(Variable_Level = as.character(Variable_Level))

df_estimated_targets <- bind_rows(
  p_X_gvn_R1_no_missing |>
    select(-Est_type) |>
    filter(X_variable != "Age"),
  age_proportions
)

# Re-code party
df_estimated_targets <- df_estimated_targets |>
  mutate(
    Variable_Level = case_when(
      tolower(X_variable) == "party" ~ recode(
        as.character(Variable_Level),
        "Republican" = "Republican",
        "Democratic" = "Democrat",
        "Registered Independent" = "Independent",
        "Non-Partisan" = "Independent",
        "Libertarian" = "Something else",
        "Constitution" = "Something else",
        "Independence" = "Something else",
        "American Independent" = "Something else",
        "Other" = "Something else",
        .default = "Something else"
      ),
      TRUE ~ as.character(Variable_Level)
    )
  )

# Bin so that sum dif parties that were coded to same thing
df_estimated_targets <- bind_rows(
  df_estimated_targets |>
    filter(tolower(X_variable) != "party"),
  df_estimated_targets |>
    filter(tolower(X_variable) == "party") |>
    group_by(X_variable, Variable_Level) |>
    summarise(
      estimate = sum(estimate, na.rm = TRUE),
      .groups = "drop"
    )
)

# Add AJPP data to the vf based df since that is what we used when not relying on Pew
p_region_gvn_R1_table <- p_state_gvn_R1_table |>
  left_join(df_state2region, by = "State") |>
  group_by(Region) |>
  summarise(
    estimate = sum(p_state_gvn_R1, na.rm = TRUE),
    .groups = "drop"
  )
colnames(p_region_gvn_R1_table) = c("Variable_Level", "estimate")
p_region_gvn_R1_table$X_variable = "Region"

df_estimated_targets <- bind_rows(
  df_estimated_targets,
  p_region_gvn_R1_table
)

# Remove Missing and renormalize
df_pew <- df_pew |>
  filter(Variable_Level != "Missing") |>
  group_by(X_variable) |>
  mutate(estimate = estimate / sum(estimate, na.rm = TRUE)) |>
  ungroup()

# Mark estimated target as one type and then combine the two
df_estimated_targets$Est_type = "Estimated target"
df_overall = rbind(df_estimated_targets, df_pew)


# Finally, create plot as before but now it's bins for each thing and includes
# Pew and Estimated Targets

plot_data <- df_overall |>
  mutate(
    X_variable = factor(
      X_variable,
      levels = c("Gender", "Age", "Party", "Region")
    ),
    Est_type = factor(Est_type, levels = c("Pew", "Estimated target"))
  )

p_combined <- ggplot(
  plot_data,
  aes(x = Variable_Level, y = estimate, fill = Est_type)
) +
  geom_col(
    position = position_dodge(width = 0.8),
    width = 0.7
  ) +
  facet_wrap(
    ~ X_variable,
    nrow = 1,
    scales = "free_x"
  ) +
  scale_fill_manual(
    values = c("Pew" = "#2166AC", "Estimated target" = "black"),
    name = NULL
  ) +
  scale_x_discrete(
    labels = function(x) stringr::str_wrap(x, width = 12)
  ) +
  scale_y_continuous(
    limits = c(0, 1),
    breaks = seq(0, 1, by = 0.2),
    expand = expansion(mult = c(0, 0))
  ) +
  labs(
    title = "Distributions Among Jewish Registered Voters",
    x = NULL,
    y = "BISG estimated fraction"
  ) +
  theme_classic(base_size = 12) +
  theme(
    plot.title = element_text(face = "bold",
                              hjust = 0.5,
                              size = 26),
    strip.background = element_blank(),
    strip.text = element_text(face = "bold", size = 22), #per-panel titles
    axis.text = element_text(color = "black"),
    axis.text.x = element_text(size = 12),
    axis.text.y = element_text(size = 14),
    axis.title.y = element_text(margin = margin(r = 10), size = 16),
    panel.spacing = grid::unit(1.2, "lines"),
    plot.margin = margin(15, 15, 15, 15),
    legend.position = "bottom",
    legend.text = element_text(size = 20)
  )

p_combined


ggsave(
  filename = file.path(save_directory, "estimated_weight_comparison_plots.pdf"),
  plot = p_combined,
  width = 18,
  height = 5,
  units = "in",
  dpi = 1200,
  bg = "white"
)



